pub fn station_by_code(code: u16) -> Option<&'static StationRecord> {
    STATIONS.iter().find(|station| station.code == code)
}

pub fn capacity_for(code: u16) -> u16 {
    station_by_code(code).map(|station| station.capacity).unwrap_or(32)
}

pub fn class_for(code: u16) -> StationClass {
    station_by_code(code).map(|station| station.class).unwrap_or_else(|| StationClass::from_nibble(code as u8))
}

pub fn callsign_for(code: u16) -> &'static str {
    station_by_code(code).map(|station| station.callsign).unwrap_or("LM-UN-0000")
}
